h2-change-subscription-when-making-a-pur.translation:
```typescript showLineNumbers
try {
    const purchaseResult = await adapty.makePurchase(product, params);
    switch (purchaseResult.type) {
      case 'success':
        const isSubscribed = purchaseResult.profile?.accessLevels['YOUR_ACCESS_LEVEL']?.isActive;

        if (isSubscribed) {
          // 有料機能へのアクセスを付与する
        }
        break;
      case 'user_cancelled':
        // ユーザーが購入をキャンセルした場合の処理
        break;
      case 'pending':
        // 延期購入を処理する（例：ユーザーが後で現金で支払う場合）
        break;
    }
} catch (error) {
    // エラーを処理する
}
```
